class RateLimitBypassTests(CommunityBooksApiTestBase):
    @mock.patch.object(cb_views, "MAX_DAILY_SUBMISSIONS", 1)
    def test_confirm_re_checks_rate_limit_after_upload_issued_extra_tokens(self):
        self._mocked_gcs()
        self._mocked_parser()
        self.client.force_login(self.user)

        upload_resp_1 = self.client.post("/api/community-books/upload", data=_upload_kwargs())
        upload_resp_2 = self.client.post("/api/community-books/upload", data=_upload_kwargs())
        self.assertEqual(upload_resp_1.status_code, 200)
        self.assertEqual(upload_resp_2.status_code, 200)  # bypass: upload() alone never sees the count grow

        token_1 = json.loads(upload_resp_1.content)["upload_token"]
        token_2 = json.loads(upload_resp_2.content)["upload_token"]

        from django.core import signing
        title_1 = signing.loads(token_1, salt="community-book-upload")["title_en"]
        title_2 = signing.loads(token_2, salt="community-book-upload")["title_en"]
        self._track(title_1)
        self._track(title_2)

        confirm_resp_1 = self.client.post(
            "/api/community-books/confirm", data=json.dumps({"upload_token": token_1}), content_type="application/json",
        )
        self.assertEqual(confirm_resp_1.status_code, 201, confirm_resp_1.content)

        confirm_resp_2 = self.client.post(
            "/api/community-books/confirm", data=json.dumps({"upload_token": token_2}), content_type="application/json",
        )
        self.assertEqual(confirm_resp_2.status_code, 429, confirm_resp_2.content)
        self.assertIsNone(Index().load({"title": title_2}))


