class MalformedArchiveTests(CommunityBooksApiTestBase):
    def _fake_docx_bytes(self):
        # A real zip (so DOCX_MAGIC + the file-under-test's zip check pass) but
        # missing the Office parts python-docx needs -> PackageNotFoundError/BadZipFile/KeyError,
        # none of which is a ParseError.
        buf = io.BytesIO()
        with zipfile.ZipFile(buf, "w") as zf:
            zf.writestr("not_a_docx_part.txt", "hello")
        return buf.getvalue()

    def test_malformed_archive_on_upload_returns_400_not_500(self):
        self.client.force_login(self.user)
        bad_file = SimpleUploadedFile("book.docx", self._fake_docx_bytes(), content_type="application/octet-stream")
        response = self.client.post("/api/community-books/upload", data=_upload_kwargs(file=bad_file))
        self.assertEqual(response.status_code, 400, response.content)

    def test_malformed_archive_on_confirm_returns_400_not_500(self):
        self._mocked_gcs()
        self.client.force_login(self.user)

        # Upload succeeds with a mocked parser (so we can reach confirm()); confirm()
        # re-parses the file it fetches from GCS, which we make return the bad bytes.
        with mock.patch.object(cb_views, "parse_document", return_value=_fake_parse_result()):
            upload_resp = self.client.post("/api/community-books/upload", data=_upload_kwargs())
        self.assertEqual(upload_resp.status_code, 200)
        token = json.loads(upload_resp.content)["upload_token"]

        from django.core import signing
        title = signing.loads(token, salt="community-book-upload")["title_en"]
        self._track(title)

        with mock.patch.object(
            cb_views.GoogleStorageManager, "get_filename", return_value=io.BytesIO(self._fake_docx_bytes())
        ):
            confirm_resp = self.client.post(
                "/api/community-books/confirm", data=json.dumps({"upload_token": token}), content_type="application/json",
            )
        self.assertEqual(confirm_resp.status_code, 400, confirm_resp.content)


