class SearchIndexingExclusionTests(TestCase):
    """
    Exercises TextIndexer.index_all()'s decision of whether to index a given
    index/version, using fake Index/Version objects in place of real
    Elasticsearch and Mongo I/O (matching the pattern already used in
    sefaria/tests/search_test.py). This does NOT exercise real Elasticsearch
    indexing -- it verifies the decision predicate that gates entry into the
    per-version indexing call.
    """

    def test_non_approved_community_book_excluded_approved_included(self):
        submitted_v = _FakeCommunityBookVersion("Submitted Book", "v1", "en", CommunityBookStatus.SUBMITTED)
        rejected_v = _FakeCommunityBookVersion("Rejected Book", "v1", "en", CommunityBookStatus.REJECTED)
        approved_v = _FakeCommunityBookVersion("Approved Book", "v1", "en", CommunityBookStatus.APPROVED)
        non_community_v = _FakeCommunityBookVersion("Regular Book", "v1", "en", None)
        all_versions = [submitted_v, rejected_v, approved_v, non_community_v]

        TextIndexer._failed_versions = []
        TextIndexer._skipped_versions = []
        TextIndexer._bulk_actions = []

        indexed_titles = []

        def fake_index_version(cls, version, tries=0, action=None):
            indexed_titles.append(version.title)

        with mock.patch.object(TextIndexer, "create_version_priority_map", classmethod(lambda cls: None)), \
             mock.patch.object(TextIndexer, "create_terms_dict", classmethod(lambda cls: None)), \
             mock.patch.object(TextIndexer, "get_all_versions", classmethod(lambda cls: list(all_versions))), \
             mock.patch.object(TextIndexer, "excluded_from_search", classmethod(lambda cls, v: False)), \
             mock.patch.object(TextIndexer, "index_version", classmethod(fake_index_version)), \
             mock.patch("sefaria.search.Ref.clear_cache", lambda: None), \
             mock.patch.object(TextIndexer, "_flush_bulk_actions", classmethod(lambda cls, versions: 0)):
            TextIndexer.version_priority_map = {
                (v.title, v.versionTitle, v.language): (i, None)
                for i, v in enumerate(all_versions)
            }
            TextIndexer.index_all(index_name="text-b", debug=False, for_es=True)

        self.assertNotIn("Submitted Book", indexed_titles)
        self.assertNotIn("Rejected Book", indexed_titles)
        self.assertIn("Approved Book", indexed_titles)
        self.assertIn("Regular Book", indexed_titles)

        skipped_reasons = {s["title"]: s.get("reason") for s in TextIndexer._skipped_versions}
        self.assertEqual(skipped_reasons.get("Submitted Book"), "community_book_not_approved")
        self.assertEqual(skipped_reasons.get("Rejected Book"), "community_book_not_approved")


class LibraryCacheRegistrationTests(CommunityBooksApiTestBase):
    """
    Guards against a newly created community book being saved with
    override_dependencies=True, which skips the observers that register the
    title in the core library cache and create its VersionState. When that
    happens, Index.save() succeeds and the document exists in Mongo, but
    Ref(title) raises InputError because the running process's in-memory
    title cache never learned about the new book -- the book becomes
    unreachable even though it was "successfully" submitted.
    """

    def test_confirmed_book_is_ref_resolvable_and_has_version_state(self):
        self._mocked_gcs()
        self._mocked_parser()
        self.client.force_login(self.user)

        upload_kwargs = _upload_kwargs()
        upload_resp = self.client.post("/api/community-books/upload", data=upload_kwargs)
        self.assertEqual(upload_resp.status_code, 200, upload_resp.content)
        token = json.loads(upload_resp.content)["upload_token"]

        from django.core import signing
        title = signing.loads(token, salt="community-book-upload")["title_en"]
        self._track(title)

        confirm_resp = self.client.post(
            "/api/community-books/confirm", data=json.dumps({"upload_token": token}), content_type="application/json",
        )
        self.assertEqual(confirm_resp.status_code, 201, confirm_resp.content)

        try:
            ref = Ref(f"{title} 1")
        except Exception as e:
            self.fail(f"Ref({title!r} 1) should resolve for a just-confirmed community book, raised: {e}")
        self.assertEqual(ref.index.title, title)

        vs = VersionState(title)
        self.assertFalse(vs.is_new_state, "VersionState should have been created on Index save")
